queries.query:
find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { distinct_count(d.stage_execution_id) as deployments }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { 100.0 * count(case when d.stage_status in ["FAILED", "ABORTED", "EXPIRED", "APPROVAL_REJECTED", "APPROVALREJECTED", "ERRORED"] then 1 end) / nullif(count(), 0) as change_failure_rate }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| filter d.stage_duration > 0
| aggregate { median(d.stage_duration) / 1000.0 as median_lead_time_s }

with f as (
  find view "cd:deployment_stage_execution" d
  | filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
  | filter d.service_identifier is not null and d.service_identifier != ""
  | filter ${project_filter_predicate} and ${service_filter_predicate}
  | filter ${environment_filter_predicate} and ${env_type_filter_predicate}
  | filter d.stage_status in ["FAILED", "ABORTED", "EXPIRED", "APPROVAL_REJECTED", "APPROVALREJECTED", "ERRORED"]
  | select { d.service_identifier as svc, d.stage_execution_id as fid, d.end_ts as fend }
),
r as (
  find f
  | join view "cd:deployment_stage_execution" s on s.service_identifier = f.svc
  | filter s.stage_status = "SUCCESS" and s.start_ts > f.fend
  | aggregate { f.fid as fid, min(f.fend) as fend, min(s.end_ts) as restored }
  | group_by fid
)
find r
| aggregate { avg(date_diff(r.fend, r.restored, "second")) as mttr_s }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { 100.0 * count(case when d.stage_status in ["FAILED", "ABORTED", "EXPIRED", "APPROVAL_REJECTED", "APPROVALREJECTED", "ERRORED"] then 1 end) / nullif(count(), 0) as change_failure_rate }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { 100.0 * count(case when d.stage_status = "SUCCESS" then 1 end) / nullif(count(), 0) as success_rate }

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    case when d.env_type = "Production" then "Production"
         when d.env_type = "PreProduction" then "Non-Production"
         else "Unclassified" end as env_class,
    distinct_count(d.stage_execution_id) as deployments
  }
| group_by env_class
| order_by deployments desc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate { d.stage_status as status, distinct_count(d.stage_execution_id) as deployments }
| group_by status
| order_by deployments desc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    date_trunc("week", d.start_ts) as week,
    case when d.stage_status in ["FAILED", "ABORTED", "EXPIRED", "APPROVAL_REJECTED", "APPROVALREJECTED", "ERRORED"] then "Failed" else "Succeeded" end as outcome,
    distinct_count(d.stage_execution_id) as deployments
  }
| group_by week, outcome
| order_by week asc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    date_trunc("week", d.start_ts) as week,
    100.0 * count(case when d.stage_status = "SUCCESS" then 1 end) / nullif(count(), 0) as success_rate,
    100.0 * count(case when d.stage_status in ["FAILED", "ABORTED", "EXPIRED", "APPROVAL_REJECTED", "APPROVALREJECTED", "ERRORED"] then 1 end) / nullif(count(), 0) as change_failure_rate
  }
| group_by week
| order_by week asc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| filter d.stage_duration > 0
| aggregate {
    date_trunc("week", d.start_ts) as week,
    median(d.stage_duration) / 1000.0 as median_lead_time_s,
    avg(d.duration) / 1000.0 as mean_pipeline_duration_s
  }
| group_by week
| order_by week asc

find view "cd:deployment_stage_execution" d
| filter d.start_ts >= cast(${start_time} as timestamp) and d.start_ts <= cast(${end_time} as timestamp)
| filter d.service_identifier is not null and d.service_identifier != ""
| filter ${project_filter_predicate} and ${service_filter_predicate}
| filter ${environment_filter_predicate} and ${env_type_filter_predicate}
| aggregate {
    d.service_name as service,
    count(case when d.stage_status = "SUCCESS" then 1 end) as succeeded,
    count(case when d.stage_status in ["FAILED", "ABORTED", "EXPIRED", "APPROVAL_REJECTED", "APPROVALREJECTED", "ERRORED"] then 1 end) as failed
  }
| group_by service
| order_by succeeded desc
| limit 10
